INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('ibm-quantum','qpu','IBM Quantum','https://quantum.ibm.com/','Flota de procesadores superconductores con acceso por nube y una hoja de ruta publica de hardware.','Es el hardware sobre el que corre la mayor parte de la literatura reproducible, y su hoja de ruta fija las expectativas del campo.','EE.UU.',200,'2026-08-09',NULL,1);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('google-quantum-ai','qpu','Google Quantum AI','https://quantumai.google/','Programa de procesadores superconductores (Sycamore, Willow) y de correccion de errores.','Publica los resultados que definen la discusion sobre supremacia y sobre umbral de correccion de errores, y tambien los que la comunidad refuta.','EE.UU.',200,'2026-08-09',NULL,2);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('quantinuum','qpu','Quantinuum','https://www.quantinuum.com/','Procesadores de iones atrapados con arquitectura QCCD y las fidelidades de dos qubits mas altas reportadas.','Es la referencia de calidad por qubit frente a la carrera por cantidad de qubits, y audita publicamente metricas de terceros.','EE.UU. / Reino Unido',200,'2026-08-09',NULL,3);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('ionq','qpu','IonQ','https://ionq.com/','Iones atrapados accesibles por las tres nubes grandes.','Su metrica propia (Algorithmic Qubits) es uno de los casos citados al discutir metricas auto-favorables de proveedor.','EE.UU.',200,'2026-08-09',NULL,4);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('quera','qpu','QuEra','https://www.quera.com/','Atomos neutros en pinzas opticas, con enfasis en arreglos reconfigurables.','Los atomos neutros cambiaron el calculo de escala del campo: cientos de qubits sin fabricacion criogenica.','EE.UU.',200,'2026-08-09',NULL,5);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('pasqal','qpu','Pasqal','https://www.pasqal.com/','Atomos neutros con foco en simulacion analogica y optimizacion.','Es el polo europeo de atomos neutros y uno de los pocos con despliegues en sitio, no solo por nube.','Francia',200,'2026-08-09',NULL,6);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('rigetti','qpu','Rigetti','https://www.rigetti.com/','Superconductores con arquitectura modular multi-chip.','Fabrica su propio silicio, lo que lo hace un punto de comparacion util sobre costos reales de la cadena.','EE.UU.',200,'2026-08-09',NULL,7);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('iqm','qpu','IQM','https://www.meetiqm.com/','Superconductores vendidos como sistema instalado en centros de supercomputo.','Representa el modelo europeo: la QPU como acelerador dentro de un HPC publico, no como servicio remoto.','Finlandia',200,'2026-08-09',NULL,8);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('alice-bob','qpu','Alice & Bob','https://alice-bob.com/','Qubits de gato (cat qubits) disenados para suprimir un tipo de error por hardware.','Apuesta a bajar el costo de la correccion de errores en la fisica, no en el software: si funciona, cambia todos los presupuestos de recursos.','Francia',200,'2026-08-09',NULL,9);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('atom-computing','qpu','Atom Computing','https://atom-computing.com/','Atomos neutros con arreglos de mas de mil qubits fisicos.','Marco el primer cruce publico de la barrera de los mil qubits fisicos, util para separar conteo de qubits de utilidad.','EE.UU.',200,'2026-08-09',NULL,10);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('d-wave','qpu','D-Wave','https://www.dwavesys.com/','Recocido cuantico (quantum annealing), un modelo distinto al de circuitos.','Es el unico proveedor con clientes de optimizacion desde hace mas de una decada, y el caso de estudio mas largo sobre cuanto de eso resiste una comparacion honesta contra solvers clasicos.','Canada',200,'2026-08-09',NULL,11);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('xanadu','qpu','Xanadu','https://www.xanadu.ai/','Fotonica en variables continuas, con hardware y software abierto.','Mantiene PennyLane, que es donde se escribe buena parte del codigo variacional que despues se compara contra clasico.','Canada',200,'2026-08-09',NULL,12);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('psiquantum','qpu','PsiQuantum','https://www.psiquantum.com/','Fotonica en silicio, apostando directo a una maquina con correccion de errores a escala de millon de qubits.','Es la apuesta que se salta la etapa NISQ por completo: no ofrece hardware intermedio, asi que su tesis solo se puede evaluar por hitos de fabricacion.','EE.UU. / Australia',200,'2026-08-09',NULL,13);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('aws-braket','qpu','Amazon Braket','https://aws.amazon.com/braket/','Nube que da acceso a QPUs de varios fabricantes con una sola cuenta.','Permite correr el mismo circuito en hardware de tecnologias distintas, que es la condicion minima para una comparacion justa.','EE.UU.',200,'2026-08-09',NULL,14);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('azure-quantum','qpu','Azure Quantum','https://azure.microsoft.com/en-us/products/quantum','Nube multi-proveedor de Microsoft, con su propia linea de qubits topologicos.','Su programa de estimacion de recursos es una de las pocas herramientas publicas para calcular cuanto hardware exigiria de verdad un algoritmo.','EE.UU.',200,'2026-08-09',NULL,15);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('qiskit','libreria','Qiskit','https://www.ibm.com/quantum/qiskit','SDK en Python para construir, transpilar y ejecutar circuitos.','Es el lenguaje comun de facto: la mayoria de los papers con codigo publican en Qiskit, asi que es donde una reproduccion empieza.',NULL,200,'2026-08-09',NULL,16);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('cirq','libreria','Cirq','https://quantumai.google/cirq','SDK de Google, con control fino sobre el circuito a nivel de compuerta y de tiempo.','Es el que se usa cuando el detalle del hardware importa para el resultado.',NULL,200,'2026-08-09',NULL,17);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('pennylane','libreria','PennyLane','https://pennylane.ai/','Libreria de diferenciacion automatica para circuitos, con puentes a PyTorch/JAX.','Es el estandar practico del trabajo variacional (QAOA, VQE), que es justo la familia mas expuesta a comparaciones injustas contra clasico.',NULL,200,'2026-08-09',NULL,18);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('cuda-q','libreria','NVIDIA CUDA-Q','https://developer.nvidia.com/cuda-q','Plataforma de programacion hibrida GPU + QPU con simuladores acelerados.','Fija el techo del baseline clasico: si una GPU simula tu circuito mas rapido de lo que tu QPU lo corre, no hay ventaja que medir.',NULL,200,'2026-08-09',NULL,19);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('tket','libreria','TKET','https://www.quantinuum.com/developers/tket','Compilador de circuitos independiente del fabricante, con optimizacion agresiva.','La calidad del compilador cambia el resultado medido: comparar sin declarar el compilador no dice nada.',NULL,200,'2026-08-09',NULL,20);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('openfermion','libreria','OpenFermion','https://quantumai.google/openfermion','Libreria para traducir problemas de estructura electronica a hamiltonianos de qubits.','Es la puerta de entrada de quimica y materiales, el area con el caso de utilidad mas defendible.',NULL,200,'2026-08-09',NULL,21);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('qutip','libreria','QuTiP','https://qutip.org/','Simulador de dinamica cuantica abierta con ruido realista.','Permite estimar cuanto del resultado prometido sobrevive al ruido antes de gastar tiempo de QPU.',NULL,200,'2026-08-09',NULL,22);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('qrisp','libreria','Qrisp','https://www.qrisp.eu/','Lenguaje de alto nivel que compila a circuitos sin escribir compuertas a mano.','Publica implementaciones de referencia de varios algoritmos del catalogo, utiles para reproducir sin reescribir desde cero.',NULL,200,'2026-08-09',NULL,23);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('classiq','libreria','Classiq','https://www.classiq.io/','Sintesis automatica de circuitos a partir de una descripcion del problema.','Mantiene implementaciones publicas enlazadas desde el catalogo canonico de algoritmos.','Israel',200,'2026-08-09',NULL,24);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('stim','libreria','Stim','https://github.com/quantumlib/Stim','Simulador de circuitos de Clifford y de codigos correctores a gran escala.','Es la herramienta con la que se verifica si una propuesta de correccion de errores realmente aguanta.',NULL,200,'2026-08-09',NULL,25);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('arxiv-quant-ph','venue','arXiv quant-ph','https://arxiv.org/list/quant-ph/recent','Repositorio de preprints donde aparece primero casi todo el campo.','Un resultado se discute aqui meses antes de tener revision por pares: es la fuente mas rapida y la que mas exige leer con criterio.',NULL,200,'2026-08-09',NULL,26);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('quantum-journal','venue','Quantum','https://quantum-journal.org/','Revista de acceso abierto sin fines de lucro, dirigida por la comunidad.','Acceso abierto real: se puede citar sin dejar al lector detras de una barrera de pago.',NULL,200,'2026-08-09',NULL,27);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('prx-quantum','venue','PRX Quantum','https://journals.aps.org/prxquantum/','Revista de la American Physical Society dedicada a informacion cuantica.','Es donde suelen aterrizar los resultados de hardware con revision cuidadosa.',NULL,403,'2026-08-09','El sitio responde 403 a clientes automatizados. Abierto a mano en un navegador el 2026-08-09.',28);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('npj-qi','venue','npj Quantum Information','https://www.nature.com/npjqi/','Revista de acceso abierto del grupo Nature.','Concentra buena parte del trabajo aplicado que despues citan los proveedores.',NULL,200,'2026-08-09',NULL,29);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('qip-conference','venue','QIP (Quantum Information Processing)','https://qipconference.org/','La conferencia anual de referencia en teoria de informacion cuantica.','Lo que se acepta en QIP marca que resultados teoricos la comunidad considera solidos.',NULL,200,'2026-08-09',NULL,30);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('shtetl-optimized','blog','Shtetl-Optimized (Scott Aaronson)','https://scottaaronson.blog/','Blog de Scott Aaronson sobre complejidad cuantica.','Es el lugar donde los claims exagerados se desarman en publico y con argumento tecnico, a veces antes que en la literatura.',NULL,200,'2026-08-09',NULL,31);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('quantum-frontiers','blog','Quantum Frontiers (Caltech IQIM)','https://quantumfrontiers.com/','Blog del instituto de informacion y materia cuantica de Caltech.','Explica resultados duros sin diluirlos, util para separar el contenido del envoltorio de prensa.',NULL,200,'2026-08-09',NULL,32);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('quantum-computing-report','blog','Quantum Computing Report','https://quantumcomputingreport.com/','Seguimiento de la industria: hardware, financiamiento y anuncios.','Es el registro mas continuo de lo que la industria dice de si misma, que es exactamente lo que hay que contrastar.',NULL,200,'2026-08-09',NULL,33);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('the-quantum-insider','blog','The Quantum Insider','https://thequantuminsider.com/','Medio de industria con base de datos de empresas y rondas de inversion.','Sus cifras de mercado circulan mucho; conviene tomarlas como dato de industria, no como medicion independiente.',NULL,200,'2026-08-09',NULL,34);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('quantum-algorithm-zoo','catalogo','Quantum Algorithm Zoo','https://quantumalgorithmzoo.org/','Catalogo canonico de algoritmos cuanticos mantenido por Stephen Jordan, con la bibliografia de cada uno.','Es la fuente de la que sale este archivador: sus entradas y su bibliografia son las que citamos fila por fila.',NULL,200,'2026-08-09',NULL,35);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('metriq','catalogo','Metriq (Unitary Foundation)','https://metriq.info/','Plataforma comunitaria de benchmarks cuanticos con resultados enviados y revisados.','Es el intento mas cercano a un registro publico de mediciones comparables, y el vecino natural de nuestro ledger.',NULL,200,'2026-08-09',NULL,36);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('unitary-foundation','catalogo','Unitary Foundation','https://unitary.foundation/','Organizacion sin fines de lucro que financia software cuantico abierto.','Financia justo la parte que nadie monetiza: herramientas de verificacion y mitigacion de errores.',NULL,200,'2026-08-09',NULL,37);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('qed-c','catalogo','QED-C','https://quantumconsortium.org/','Consorcio de industria y gobierno que publica suites de benchmarks orientadas a aplicaciones.','Sus benchmarks son de los pocos disenados por comite en vez de por el propio vendedor.','EE.UU.',200,'2026-08-09',NULL,38);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('nist-pqc','estandar','NIST Post-Quantum Cryptography','https://csrc.nist.gov/projects/post-quantum-cryptography','Programa de estandarizacion de criptografia resistente a computadores cuanticos.','Es la unica consecuencia practica y ya obligatoria de la amenaza cuantica: fija el reloj de migracion de todo el mundo.','EE.UU.',200,'2026-08-09',NULL,39);
INSERT INTO quantum_sources (id,tipo,nombre,url,que_es,por_que_importa,pais,http_status,verificado_at,nota_enlace,orden) VALUES ('iso-iec-jtc1-wg14','estandar','ISO/IEC JTC 1/WG 14 — Quantum Information Technology','https://jtc1info.org/sd-2-history/jtc1-working-groups/wg-14/','Grupo de trabajo internacional que coordina el programa de estandarizacion de tecnologia cuantica dentro de JTC 1.','Cuando el vocabulario se estandariza, las metricas de proveedor dejan de poder significar cualquier cosa.',NULL,200,'2026-08-09',NULL,40);
INSERT INTO quantum_algorithms (id,nombre,categoria,categoria_id,problema_es,speedup_declarado,fuente_nombre,fuente_url,ancla,refs_json,impl_json,remisiones_json,n_refs,orden) VALUES ('factoring','Factoring','Algebraic and Number Theoretic Algorithms','algebraic','Descomponer un entero de n bits en sus factores primos. Es el problema sobre el que descansa RSA.','Superpolynomial','Quantum Algorithm Zoo','https://quantumalgorithmzoo.org/#algebraic','algebraic','[{"n":82,"cita":"Peter W. Shor Polynomial-time algorithms for prime factorization and discrete logarithms on a quantum computer. SIAM Journal on Computing , 26(5):1484-1509, 1997. [ arXiv:quant-ph/9508027 ]","url":"http://arxiv.org/abs/quant-ph/9508027"},{"n":125,"cita":"Peter Shor Algorithms for Quantum Computation: Discrete Logarithms and Factoring. In Proceedings of FOCS 1994 , pg. 124-134.","url":null},{"n":248,"cita":"Daniel J. Bernstein, Johannes Buchmann, and Erik Dahmen, Eds. Post-Quantum Cryptography Springer , 2009.","url":"http://www.springer.com/mathematics/numbers/book/978-3-540-88701-0"},{"n":252,"cita":"J. M. Pollard Theorems on factorization and primality testing Proceedings of the Cambridge Philosophical Society. 76:521-228, 1974.","url":null},{"n":253,"cita":"L. Babai, R. Beals, and A. Seress Polynomial-time theory of matrix groups In Proceedings of STOC 2009 , pg. 55-64.","url":null},{"n":254,"cita":"Neil J. Ross and Peter Selinger Optimal ancilla-free Clifford+T approximations of z-rotations arXiv:1403.2975 , 2014.","url":"http://arxiv.org/abs/1403.2975"},{"n":271,"cita":"Fr&eacute;d&eacute;ric Grosshans, Thomas Lawson, Fran&ccedil;ois Morain, and Benjamin Smith Factoring safe semiprimes with a single quantum query arXiv:1511.04385 , 2015.","url":"http://arxiv.org/abs/1511.04385"},{"n":362,"cita":"Volker Strassen Einige Resultate &uuml;ber Berechnungskomplexit&auml;t In Jahresbericht der Deutschen Mathematiker-Vereinigung , 78(1):1-8, 1976/1977.","url":null},{"n":366,"cita":"D. J. Bernstein, N. Heninger, P. Lou, and L. Valenta Post-quantum RSA IACR e-print 2017/351 , 2017.","url":"https://eprint.iacr.org/2017/351"},{"n":384,"cita":"M. Eker&aring; and J. H&aring;stad Quantum Algorithms for Computing Short Discrete Logarithms and Factoring RSA Integers Proceedings of PQCrypto 2017 , pg. 347-363. (LNCS Volume 10346), 2017.","url":"https://link.springer.com/chapter/10.1007/978-3-319-59879-6_20"},{"n":386,"cita":"D. J. Bernstein, J.-F. Biasse, and M. Mosca A low-resource quantum factoring algorithm Proceedings of PQCrypto 2017 , pg. 330-346 (LNCS Volume 10346), 2017.","url":"https://link.springer.com/chapter/10.1007/978-3-319-59879-6_19"},{"n":431,"cita":"Craig Gidney and Martin Ekera How to factor 2048 bit RSA integers in 8 hours using 20 million noisy qubits Quantum 5:433, 2021. [ arXiv:1905.09749 ]","url":"https://arxiv.org/abs/1905.09749"},{"n":542,"cita":"David Harvey and Markus Hittmeir A log-log speedup for exponent one-fifth deterministic integer factorization arXiv:2105.11105 , 2021.","url":"https://arxiv.org/abs/2105.11105"}]','[{"nombre":"Classiq","url":"https://short.classiq.io/shor"},{"nombre":"Cirq","url":"https://github.com/quantumlib/Cirq/blob/main/examples/shor.py"},{"nombre":"PennyLane","url":"https://pennylane.ai/codebook/shors-algorithm"},{"nombre":"Qrisp","url":"https://qrisp.eu/reference/Algorithms/Shor.html#shor"}]','["abelian_HSP"]',13,1);
INSERT INTO quantum_algorithms (id,nombre,categoria,categoria_id,problema_es,speedup_declarado,fuente_nombre,fuente_url,ancla,refs_json,impl_json,remisiones_json,n_refs,orden) VALUES ('discrete-log','Discrete-log','Algebraic and Number Theoretic Algorithms','algebraic','Dado b = a^s mod N, encontrar s. Sostiene DSA, ECDSA y el intercambio de claves Diffie-Hellman.','Superpolynomial','Quantum Algorithm Zoo','https://quantumalgorithmzoo.org/#algebraic','algebraic','[{"n":14,"cita":"D. Boneh and R. J. Lipton Quantum cryptanalysis of hidden linear functions. In Don Coppersmith, editor, CRYPTO ''95 , Lecture Notes in Computer Science, pages 424-437. Springer-Verlag, 1995.","url":null},{"n":82,"cita":"Peter W. Shor Polynomial-time algorithms for prime factorization and discrete logarithms on a quantum computer. SIAM Journal on Computing , 26(5):1484-1509, 1997. [ arXiv:quant-ph/9508027 ]","url":"http://arxiv.org/abs/quant-ph/9508027"},{"n":109,"cita":"John Proos and Christof Zalka Shor''s discrete logarithm quantum algorithm for elliptic curves. Quantum Information and Computation , Vol. 3, No. 4, pg.317-344, 2003. [ arXiv:quant-ph/0301141 ]","url":"http://arxiv.org/abs/quant-ph/0301141"},{"n":203,"cita":"Andrew Childs and G&aacute;bor Ivanyos Quantum computation of discrete logarithms in semigroups. arXiv:1310.6238 , 2013.","url":"http://arxiv.org/abs/1310.6238"},{"n":204,"cita":"Matan Banin and Boaz Tsaban A reduction of semigroup DLP to classic DLP. arXiv:1310.7903 , 2013.","url":"http://arxiv.org/abs/1310.7903"},{"n":385,"cita":"M. Eker&aring; On post-processing in the quantum algorithm for computing short discrete logarithms IACR ePrint Archive Report 2017/1122 , 2017.","url":"https://eprint.iacr.org/2017/1122"},{"n":432,"cita":"Martin Roetteler, Michael Naehrig, Krysta M. Svore, and Kristin Lauter Quantum resource estimates for computing elliptic curve discrete logarithms Proceedings of ASIACRYPT 2017 [ arXiv:1706.06752 ]","url":"https://arxiv.org/abs/1706.06752"}]','[{"nombre":"Classiq","url":"https://short.classiq.io/discrete_log"},{"nombre":"Qrisp","url":"https://github.com/diehoq/quantum-elliptic-curve-logarithm"}]','["abelian_HSP"]',7,2);
INSERT INTO quantum_algorithms (id,nombre,categoria,categoria_id,problema_es,speedup_declarado,fuente_nombre,fuente_url,ancla,refs_json,impl_json,remisiones_json,n_refs,orden) VALUES ('pell-s-equation','Pell''s Equation','Algebraic and Number Theoretic Algorithms','algebraic','Resolver la ecuacion de Pell x^2 - d*y^2 = 1 sobre los enteros. Romperla quiebra el criptosistema de Buchmann-Williams.','Superpolynomial','Quantum Algorithm Zoo','https://quantumalgorithmzoo.org/#algebraic','algebraic','[{"n":49,"cita":"Sean Hallgren Polynomial-time quantum algorithms for Pell''s equation and the principal ideal problem. In Proceedings of the 34th ACM Symposium on Theory of Computing , 2002.","url":null}]','[]','["abelian_HSP"]',1,3);
