INSERT INTO quantum_algorithms (id,nombre,categoria,categoria_id,problema_es,speedup_declarado,fuente_nombre,fuente_url,ancla,refs_json,impl_json,remisiones_json,n_refs,orden) VALUES ('abelian-hidden-subgroup','Abelian Hidden Subgroup','Oracular Algorithms','oracular','Hallar un subgrupo oculto de un grupo conmutativo consultando una funcion que es constante en cada coclase. Es el patron comun detras de Shor: factorizar, logaritmo discreto y Pell se reducen todos a esto.','Superpolynomial','Quantum Algorithm Zoo','https://quantumalgorithmzoo.org/#abelian_HSP','abelian_HSP','[{"n":14,"cita":"D. Boneh and R. J. Lipton Quantum cryptanalysis of hidden linear functions. In Don Coppersmith, editor, CRYPTO ''95 , Lecture Notes in Computer Science, pages 424-437. Springer-Verlag, 1995.","url":null},{"n":30,"cita":"J. Niel de Beaudrap, Richard Cleve, and John Watrous Sharp quantum versus classical query complexity separations. Algorithmica , 34(4):449-461, 2002. [ arXiv:quant-ph/0011065v2 ]","url":"http://arxiv.org/abs/quant-ph/0011065"},{"n":76,"cita":"Michael A. Nielsen and Isaac L. Chuang. Quantum Computation and Quantum Information . Cambridge University Press, Cambridge, UK, 2000.","url":null},{"n":108,"cita":"D. Simon On the Power of Quantum Computation. In Proceedings of the 35th Symposium on Foundations of Computer Science , pg. 116-123, 1994.","url":null},{"n":388,"cita":"Lisa Hales and Sean Hallgren An improved quantum Fourier transform algorithm and applications. In Proceedings of FOCS 2000 , pg. 515-525.","url":null},{"n":389,"cita":"Igor Shparlinski and Arne Winterhof Quantum period reconstruction of approximate sequences Information Processing Letters , 103:211-215, 2007.","url":null}]','[{"nombre":"Classiq","url":"https://short.classiq.io/simon"},{"nombre":"Cirq","url":"https://github.com/quantumlib/Cirq/blob/main/examples/simon_algorithm.py"}]','[]',6,16);
